const baseUrl = String(env.get('TRACE_API_URL') || '').replace(/\/$/, '');
const traceToken = String(env.get('TRACE_DEVICE_TOKEN') || '').trim();
if (!baseUrl || !traceToken || /[,;\n]/.test(traceToken)) return null;
msg.traceToken = traceToken;
msg.url = `${baseUrl}/api/equipamentos_gateway.php`;
msg.method = 'GET';
msg.headers = { 'X-Device-Token': traceToken };
return msg;

if (msg.statusCode !== 200) return [[], []];
const equipment = Array.isArray(msg.payload?.data) ? msg.payload.data : [];
const baseUrl = String(env.get('TRACE_API_URL') || '').replace(/\/$/, '');
const traceToken = String(msg.traceToken || '');
if (!equipment.length || !baseUrl || !traceToken) return [[], []];
const defaultUnit = String(env.get('TRACE_MODBUS_UNIT_ID') || '1').trim();
const defaultFunction = String(env.get('TRACE_MODBUS_HEARTBEAT_FUNCTION') || '1').trim();
const defaultRegister = String(env.get('TRACE_MODBUS_HEARTBEAT_REGISTER') || '2052').trim();
const validConfig = (unit, fc, register) => /^\d+$/.test(unit) && /^\d+$/.test(fc) && /^\d+$/.test(register)
    && Number(unit) >= 0 && Number(unit) <= 255 && [1, 2, 3, 4].includes(Number(fc)) && Number(register) <= 65535;
const probes = [];
const watchdogs = [];
for (const item of equipment) {
    const equipmentId = Number(item.id);
    const host = String(item.plc_connect_ip || '').trim();
    const port = Number(item.plc_port || 0);
    const protocol = String(item.plc_protocol || 'MODBUS_TCP').toUpperCase();
    watchdogs.push({ ...msg, traceToken, equipmentId, url: `${baseUrl}/api/device_heartbeat.php`, method: 'POST', headers: { 'X-Device-Token': traceToken, 'Content-Type': 'application/json' }, payload: { equipment_id: equipmentId, device_type: 'CLP', status: 'OFFLINE', details: { source: 'node-red', communication: 'modbus_tcp', reason: 'sem_resposta_modbus' } } });
    const unit = String(item.modbus_unit_id ?? defaultUnit).trim();
    const fc = String(item.modbus_heartbeat_function ?? defaultFunction).trim();
    const register = String(item.modbus_heartbeat_register ?? defaultRegister).trim();
    if (equipmentId > 0 && host && Number.isInteger(port) && port >= 1 && port <= 65535 && protocol === 'MODBUS_TCP' && validConfig(unit, fc, register)) {
        probes.push({ ...msg, traceToken, equipmentId, modbusHost: host, modbusPort: port, modbusUnit: Number(unit), modbusFunction: Number(fc), modbusRegister: Number(register), payload: null });
    }
}
return [probes, watchdogs];

const rawUnit = String(msg.modbusUnit ?? env.get('TRACE_MODBUS_UNIT_ID') ?? '1').trim();
const rawFunction = String(msg.modbusFunction ?? env.get('TRACE_MODBUS_HEARTBEAT_FUNCTION') ?? '1').trim();
const rawRegister = String(msg.modbusRegister ?? env.get('TRACE_MODBUS_HEARTBEAT_REGISTER') ?? '2052').trim();
if (![rawUnit, rawFunction, rawRegister].every(value => /^\d+$/.test(value))) return null;
const unit = Number(rawUnit), fc = Number(rawFunction), register = Number(rawRegister);
if (unit < 0 || unit > 255 || ![1, 2, 3, 4].includes(fc) || register > 65535) return null;
const transaction = ((flow.get('modbus_transaction') || 0) + 1) & 0xffff;
flow.set('modbus_transaction', transaction);
const frame = Buffer.alloc(12);
frame.writeUInt16BE(transaction, 0);
frame.writeUInt16BE(6, 4);
frame[6] = unit;
frame[7] = fc;
frame.writeUInt16BE(register, 8);
frame.writeUInt16BE(1, 10);
msg.modbusTransaction = transaction;
msg.modbusUnit = unit;
msg.modbusFunction = fc;
msg.modbusRegister = register;
msg.modbusStartedAt = Date.now();
msg.payload = frame;
msg.host = msg.modbusHost;
msg.port = msg.modbusPort;
return msg;

const frame = Buffer.isBuffer(msg.payload) ? msg.payload : Buffer.alloc(0);
const age = Date.now() - Number(msg.modbusStartedAt);
const functionCode = Number(msg.modbusFunction);
const bitRead = [1, 2].includes(functionCode);
const expectedBytes = bitRead ? 1 : 2;
const expectedPduLength = 3 + expectedBytes;
const valid = Number.isFinite(age) && age >= 0 && age <= 2000
    && frame.length === 7 + 2 + expectedBytes && frame.readUInt16BE(0) === msg.modbusTransaction
    && frame.readUInt16BE(2) === 0 && frame.readUInt16BE(4) === expectedPduLength
    && frame[6] === msg.modbusUnit && frame[7] === functionCode
    && [1, 2, 3, 4].includes(functionCode) && frame[8] === expectedBytes;
if (!valid) return null;
flow.set(`modbus_last_success_${msg.equipmentId}`, Date.now());
const baseUrl = String(env.get('TRACE_API_URL') || '').replace(/\/$/, '');
if (!baseUrl || !msg.traceToken) return null;
msg.url = `${baseUrl}/api/device_heartbeat.php`;
msg.method = 'POST';
msg.headers = { 'X-Device-Token': msg.traceToken, 'Content-Type': 'application/json' };
const diagnosticValue = bitRead ? (frame[9] & 1) : frame.readUInt16BE(9);
msg.payload = { equipment_id: msg.equipmentId, device_type: 'CLP', status: 'ONLINE', details: {
    source: 'node-red', communication: 'modbus_tcp', plc_ip: msg.modbusHost, plc_port: msg.modbusPort,
    modbus_unit_id: msg.modbusUnit, modbus_function: functionCode,
    diagnostic_register: msg.modbusRegister, diagnostic_value: diagnosticValue, heartbeat_interval_ms: 1000
} };
return msg;

const lastSuccess = flow.get(`modbus_last_success_${msg.equipmentId}`) || 0;
if (lastSuccess && Date.now() - lastSuccess < 3500) return null;
return msg;

const baseUrl = String(env.get('TRACE_API_URL') || '').replace(/\/$/, '');
const traceToken = String(env.get('TRACE_DEVICE_TOKEN') || '').trim();
if (!baseUrl || !traceToken || /[,;\n]/.test(traceToken)) return null;
msg.traceToken = traceToken;
msg.url = `${baseUrl}/api/equipamentos_gateway.php`;
msg.method = 'GET';
msg.headers = { 'X-Device-Token': traceToken };
return msg;

if (msg.statusCode !== 200) return null;
const equipment = Array.isArray(msg.payload?.data) ? msg.payload.data : [];
const baseUrl = String(env.get('TRACE_API_URL') || '').replace(/\/$/, '');
const traceToken = String(msg.traceToken || '');
if (!equipment.length || !baseUrl || !traceToken) return null;
return [equipment.map(item => ({ ...msg, traceToken, url: `${baseUrl}/api/plc_gateway.php`, method: 'POST', headers: { 'X-Device-Token': traceToken, 'Content-Type': 'application/json' }, payload: { action: 'CLAIM', equipment_id: Number(item.id) } }))];

if (msg.statusCode !== 200) return null;
const response = msg.payload && (msg.payload.data || msg.payload);
if (!response || !response.id) return null;
const command = String(response.command || '');
const supported = ['EMERGENCIA', 'REVERSAO_ATIVAR', 'REVERSAO_DESATIVAR', 'DESBLOQUEAR_MAQUINA', 'INICIAR_CARREGAMENTO', 'PAUSAR_CARREGAMENTO'];
const installationMode = String(env.get('TRACE_INSTALLATION_MODE') || '').toLowerCase();
const simulatorOnly = String(env.get('TRACE_LOCAL_SIMULATION') || '0') === '1'
    && String(env.get('TRACE_SIMULATOR_ONLY_COMMANDS') || '0') === '1'
    && ['local', 'industrial'].includes(installationMode);
let status = supported.includes(command) ? 'REJEITADO' : 'ERRO';
let reason = status === 'REJEITADO'
    ? 'Mapa de I/O do CLP ainda não aprovado; nenhuma escrita foi executada. A solicitação não confirma movimento nem parada física.'
    : 'Comando não suportado pelo gateway local.';
if (command === 'EMERGENCIA') {
    status = 'REJEITADO';
    reason = 'A emergência deve ser acionada fisicamente. Nenhum comando de emergência foi enviado pelo Trace.';
} else if (simulatorOnly && supported.includes(command)) {
    const loadingId = String(response.carregamento_id || '');
    const states = flow.get('trace_simulated_loading_states') || {};
    const simulated = states[loadingId] || {
        loading_state: String(response.loading_state || ''),
        reversal_active: false,
    };
    const transitions = {
        INICIAR_CARREGAMENTO: { from: ['AGUARDANDO', 'PREPARANDO', 'PAUSADO'], to: 'CARREGANDO' },
        PAUSAR_CARREGAMENTO: { from: ['CARREGANDO'], to: 'PAUSADO' },
        REVERSAO_ATIVAR: { from: ['PAUSADO'], to: 'PAUSADO' },
        REVERSAO_DESATIVAR: { from: ['PAUSADO'], to: 'PAUSADO' },
        DESBLOQUEAR_MAQUINA: { from: ['EMERGENCIA'], to: 'PREPARANDO' },
    };
    const transition = transitions[command];
    if (!transition) {
        status = 'ERRO';
        reason = 'Comando não suportado pelo simulador local.';
    } else if (!transition.from.includes(simulated.loading_state)) {
        status = 'REJEITADO';
        reason = `SIMULAÇÃO LOCAL: ${command} não permitido no estado ${simulated.loading_state || 'DESCONHECIDO'}. Nenhuma escrita Modbus ou saída física foi acionada.`;
    } else {
        simulated.loading_state = transition.to;
        if (command === 'REVERSAO_ATIVAR') simulated.reversal_active = true;
        if (command === 'REVERSAO_DESATIVAR') simulated.reversal_active = false;
        states[loadingId] = simulated;
        flow.set('trace_simulated_loading_states', states);
        status = 'APLICADO';
        reason = `SIMULAÇÃO LOCAL: ${command} confirmado; estado simulado ${simulated.loading_state}, reversão ${simulated.reversal_active ? 'ativa' : 'inativa'}. Nenhuma escrita Modbus ou saída física foi acionada.`;
    }
}
const baseUrl = String(env.get('TRACE_API_URL') || '').replace(/\/$/, '');
const token = String(msg.traceToken || '');
if (!baseUrl || !token) return null;
msg.url = `${baseUrl}/api/plc_gateway.php`;
msg.method = 'POST';
msg.headers = {
    'X-Device-Token': token,
    'Content-Type': 'application/json'
};
msg.payload = { action: 'COMPLETE', request_id: Number(response.id), status, message: reason };
return msg;
